// Builds supabase/seed.sql from content/world.json + content/units.json.
// Deterministic (seeded shuffle) so the generated file is stable in git.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const world = JSON.parse(readFileSync(join(root, 'content/world.json'), 'utf8'));
const book = JSON.parse(readFileSync(join(root, 'content/units.json'), 'utf8'));

// ---- tiny seeded RNG ----
let seed = 20260101;
const rnd = () => {
  seed = (seed * 1664525 + 1013904223) % 4294967296;
  return seed / 4294967296;
};
const shuffle = (arr) => {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};
const pick = (arr, n) => shuffle(arr).slice(0, n);
const q = (v) => (v === null || v === undefined ? 'null' : `'${String(v).replace(/'/g, "''")}'`);
const j = (v) => `${q(JSON.stringify(v))}::jsonb`;
const textArr = (a) => `array[${a.map(q).join(',')}]::text[]`;

const hasEllipsis = (s) => s.includes('...');
const tokens = (s) => s.split(/\s+/).filter(Boolean);

function buildActivities(lesson, unitLessons) {
  if (lesson.kind === 'project') {
    return [{ type: 'project', payload: { title: lesson.project } }];
  }
  const acts = [];
  const lessonWords = (lesson.groups ?? []).flatMap((g) => g.words);
  const unitWords = [...new Set(unitLessons.flatMap((l) => (l.groups ?? []).flatMap((g) => g.words)))];
  const unitAnswers = unitLessons.flatMap((l) => (l.qa ?? []).map((x) => x.a));
  const unitQ = unitLessons.flatMap((l) => (l.qa ?? []).map((x) => x));

  // listen & choose: any vocabulary item (single words and short phrases)
  for (const w of pick(lessonWords, 4)) {
    const group = lesson.groups.find((g) => g.words.includes(w));
    let pool = group.words.filter((x) => x !== w);
    if (pool.length < 3) {
      const extra = unitWords.filter((x) => x !== w && !pool.includes(x));
      // prefer look-alike distractors (same number of words) before anything else
      extra.sort((a, b) => Math.abs(tokens(a).length - tokens(w).length) - Math.abs(tokens(b).length - tokens(w).length));
      pool = [...pool, ...extra.slice(0, 6)];
    }
    if (pool.length < 3) continue;
    acts.push({ type: 'listen_choose', payload: { say: w, answer: w, choices: shuffle([w, ...pick(pool, 3)]) } });
  }
  // spelling: single alphabetic words
  const spellable = lessonWords.filter((w) => /^[A-Za-z]{3,12}$/.test(w));
  for (const w of pick(spellable, 2)) {
    acts.push({ type: 'spell', payload: { say: w, answer: w } });
  }
  // sentence order: printed sentences and 3+ word phrases
  const orderable = [
    ...(lesson.sentences ?? []),
    ...lessonWords.filter((w) => tokens(w).length >= 3),
  ].filter((s) => !hasEllipsis(s) && tokens(s).length >= 2 && tokens(s).length <= 18);
  for (const s of pick(orderable, 3)) {
    acts.push({ type: 'sentence_order', payload: { say: s, answer: s } });
  }
  // question & answer
  for (const item of pick((lesson.qa ?? []).filter((x) => !hasEllipsis(x.q) && !hasEllipsis(x.a)), 3)) {
    const sameQ = unitQ.filter((x) => x.q === item.q).map((x) => x.a);
    const pool = [...new Set(unitAnswers)].filter((a) => !sameQ.includes(a));
    if (pool.length < 2) continue;
    const wrong = pick(pool, Math.min(3, pool.length));
    acts.push({ type: 'qa_choose', payload: { question: item.q, say: item.q, answer: item.a, choices: shuffle([item.a, ...wrong]) } });
  }
  // interleave types so a lesson is not 4 identical activities in a row
  const order = ['listen_choose', 'qa_choose', 'spell', 'sentence_order'];
  const byType = Object.fromEntries(order.map((t) => [t, acts.filter((a) => a.type === t)]));
  const mixed = [];
  while (mixed.length < acts.length) {
    for (const t of order) if (byType[t].length) mixed.push(byType[t].shift());
  }
  return mixed;
}

const out = [];
out.push('-- GENERATED by scripts/build-seed.mjs from content/*.json. Do not edit by hand.');
out.push('-- Safe to re-run: content is upserted, player data is untouched.');
out.push('begin;');

for (const l of world.locations) {
  out.push(
    `insert into public.locations (id, kind, name_en, name_th, blurb_th, icon, page_from, page_to, x, y, requires, rest_type, content_status) values (` +
      [q(l.id), q(l.kind), q(l.name_en), q(l.name_th), q(l.blurb_th), q(l.icon), l.pages?.[0] ?? 'null', l.pages?.[1] ?? 'null', l.x, l.y,
        textArr(l.requires ?? []), q(l.rest_type ?? null), q(l.content_status ?? 'verified')].join(', ') +
      `) on conflict (id) do update set kind=excluded.kind, name_en=excluded.name_en, name_th=excluded.name_th, blurb_th=excluded.blurb_th, icon=excluded.icon, page_from=excluded.page_from, page_to=excluded.page_to, x=excluded.x, y=excluded.y, requires=excluded.requires, rest_type=excluded.rest_type, content_status=excluded.content_status;`,
  );
}
out.push(`delete from public.location_paths;`);
for (const [a, b] of world.paths) out.push(`insert into public.location_paths values (${q(a)}, ${q(b)});`);

for (const it of world.items) {
  out.push(
    `insert into public.items values (${[q(it.id), q(it.name_en), q(it.name_th), q(it.icon), q(it.kind), it.heal_hp, it.heal_mana, it.price].join(', ')}) on conflict (id) do update set name_en=excluded.name_en, name_th=excluded.name_th, icon=excluded.icon, kind=excluded.kind, heal_hp=excluded.heal_hp, heal_mana=excluded.heal_mana, price=excluded.price;`,
  );
}
for (const p of world.pet_species) {
  out.push(
    `insert into public.pet_species values (${[q(p.id), q(p.name_en), q(p.name_th), q(p.icon), q(p.skill_name), q(p.blurb_th)].join(', ')}) on conflict (id) do update set name_en=excluded.name_en, name_th=excluded.name_th, icon=excluded.icon, skill_name=excluded.skill_name, blurb_th=excluded.blurb_th;`,
  );
}

let total = 0;
for (const [locId, lessons] of Object.entries(book.units)) {
  lessons.forEach((lesson, idx) => {
    out.push(
      `insert into public.lessons (id, location_id, sort, kind, title, pages, required, pass_ratio) values (${[
        q(lesson.id), q(locId), idx + 1, q(lesson.kind), q(lesson.title), q(lesson.pages ?? null), lesson.required === false ? 'false' : 'true', lesson.pass_ratio ?? 0,
      ].join(', ')}) on conflict (id) do update set location_id=excluded.location_id, sort=excluded.sort, kind=excluded.kind, title=excluded.title, pages=excluded.pages, required=excluded.required;`,
    );
    out.push(`delete from public.activities where lesson_id = ${q(lesson.id)};`);
    const acts = buildActivities(lesson, lessons);
    total += acts.length;
    acts.forEach((a, i) => {
      out.push(`insert into public.activities (lesson_id, sort, type, payload) values (${q(lesson.id)}, ${i + 1}, ${q(a.type)}, ${j(a.payload)});`);
    });
  });
}
out.push('commit;');
writeFileSync(join(root, 'supabase/seed.sql'), out.join('\n') + '\n');
console.log(`seed.sql written: ${world.locations.length} locations, ${total} activities`);
